package com.volna.inventory_service.controller;import com.volna.inventory_service.dto.vendor.*;import com.volna.inventory_service.security.AuthenticatedUser;import com.volna.inventory_service.service.InventoryVendorService;import jakarta.validation.Valid;import com.volna.inventory_service.exception.BadRequestException;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/inventory/vendors") public class InventoryVendorController{private final InventoryVendorService s;public InventoryVendorController(InventoryVendorService s){this.s=s;}@GetMapping public Page<VendorResponse> all(@AuthenticationPrincipal AuthenticatedUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100)throw new BadRequestException("page must be >= 0 and size must be between 1 and 100");return s.all(u.authUserId(),PageRequest.of(page,size));}@GetMapping("/{id}")public VendorResponse get(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){return s.get(u.authUserId(),id);}@PostMapping public ResponseEntity<VendorResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreateVendorRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(u.authUserId(),q));}@PutMapping("/{id}")public VendorResponse update(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id,@Valid @RequestBody UpdateVendorRequest q){return s.update(u.authUserId(),id,q);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){s.delete(u.authUserId(),id);return ResponseEntity.noContent().build();}}
